/* Airport Projects Radar - dashboard logic. Data comes from data/*.js (generated by refresh/Build-Data.ps1 and Refresh-Feeds.ps1). */
(function () {
  'use strict';
  const TODAY = new Date('2026-09-11T00:00:00');
  const DAY = 86400000;
  const REGIONS = ['Europe', 'Middle East', 'North Africa', 'Central Asia', 'Asia Pacific', 'Australia', 'North America'];
  const TYPES = ['Greenfield airport', 'Passenger terminals', 'Runways & airfield', 'Cargo & logistics', 'Landside & intermodal', 'Utilities, sustainability & digital', 'Master plans, feasibility & PPP'];
  const STAGE_GROUPS = [
    ['Completed', /completed|operational/i], ['Cancelled', /cancelled/i], ['Suspended', /suspended/i],
    ['Commissioning', /commissioning/i], ['Construction', /construction/i], ['Procurement', /procurement/i],
    ['Design', /design/i], ['Approvals & consent', /approval|consent|master plan/i], ['Planning & feasibility', /planning|feasib/i]
  ];
  // Approximate USD conversion for scale scoring / sorting only (not shown as a converted value). Rates indicative, Sept 2026.
  const FX = { USD: 1, EUR: 1.1, GBP: 1.3, CHF: 1.15, PLN: 0.26, AUD: 0.66, NZD: 0.6, SAR: 0.267, AED: 0.272, MAD: 0.105, THB: 0.029, PHP: 0.0175, INR: 0.0118, MYR: 0.23, TWD: 0.031, IDR: 0.000062 };
  const UNIT = { bn: 1e9, m: 1e6, tn: 1e12, cr: 1e7 };
  const LOCAL = /^(localhost|127\.0\.0\.1)$/.test(location.hostname);

  const $ = (s, r) => (r || document).querySelector(s);
  const $$ = (s, r) => Array.from((r || document).querySelectorAll(s));
  const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const fmtDate = (d) => { if (!d) return ''; const m = /^(\d{4})-(\d{2})(?:-(\d{2}))?/.exec(d); if (!m) return d; const mo = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][+m[2] - 1]; return m[3] ? `${+m[3]} ${mo} ${m[1]}` : `${mo} ${m[1]}`; };
  const parseDate = (d) => { if (!d) return null; const m = /^(\d{4})-(\d{2})(?:-(\d{2}))?/.exec(d); if (!m) return null; return new Date(+m[1], +m[2] - 1, m[3] ? +m[3] : 1); };
  const nd = (s) => s || 'Not publicly disclosed';
  const fmtStamp = (iso) => { const d = iso ? new Date(iso) : null; return d && !isNaN(d) ? d.toLocaleString('en-GB', { dateStyle: 'medium', timeStyle: 'short' }) : 'Not recorded'; };

  // ---------- State ----------
  let RAW = window.AMI_PROJECTS || [];
  let SOURCES = window.AMI_SOURCES || { sources: [], gaps: [] };
  let REFRESH = window.AMI_REFRESH || {};
  let SIGNALS = window.AMI_SIGNALS || { projects: {}, unmatched: [], dismissed: [] };
  let P = [], byId = {};

  function derive() {
    P = RAW.map((r) => {
      const s = r.score || {};
      const total = (s.fit | 0) + (s.timing | 0) + (s.access | 0) + (s.scale | 0) + (s.evidence | 0);
      const stageGroup = (STAGE_GROUPS.find(([, re]) => re.test(r.stage || '')) || ['Planning & feasibility'])[0];
      const active = !/^(Completed|Cancelled|Suspended)$/.test(stageGroup);
      const priority = !active ? 'Context' : total >= 15 ? 'High' : total >= 10 ? 'Medium' : 'Low';
      const ot = r.opportunity_type || '';
      const procKind = /^Confirmed/.test(ot) ? 'confirmed' : /^Existing/.test(ot) ? 'existing' : /^Potential/.test(ot) ? 'potential' : 'track';
      const v = r.value || {};
      const usd = v.amount && v.currency ? v.amount * (UNIT[v.unit] || 1) * (FX[v.currency] || 0) : 0;
      const latest = parseDate(r.dates && r.dates.latest_update);
      const staleDays = latest ? Math.floor((TODAY - latest) / DAY) : null;
      const flags = (r.flags || []).slice();
      if (staleDays != null && staleDays > 180 && !flags.some((f) => /stale/i.test(f))) flags.push(`Stale - latest update ${staleDays} days ago`);
      const ms = (r.milestones || []).map((m) => ({ ...m, dt: parseDate(m.date) })).filter((m) => m.dt).sort((a, b) => a.dt - b.dt);
      const next = ms.find((m) => m.dt >= TODAY) || null;
      const overdue = ms.filter((m) => m.dt < TODAY && /overdue|verify/i.test(m.when || ''));
      const isNew = (parseDate(r.first_identified) || TODAY) >= new Date(TODAY - 30 * DAY);
      const signals = (SIGNALS.projects && SIGNALS.projects[r.id]) || [];
      return { ...r, total, stageGroup, active, priority, procKind, usd, latest, staleDays, flags, ms, next, overdue, isNew, signals };
    });
    byId = Object.fromEntries(P.map((p) => [p.id, p]));
  }

  // ---------- Filters ----------
  const F = { search: '', regions: new Set(), country: '', airport: '', types: new Set(), stage: '', proc: '', priority: '', since: '', flagged: false, context: true };
  function buildFilterUI() {
    $('#fRegion').innerHTML = REGIONS.map((r) => `<label><input type="checkbox" value="${esc(r)}"> ${esc(r)} <span class="mono" style="color:var(--muted)">${P.filter((p) => p.region === r).length}</span></label>`).join('');
    $('#fType').innerHTML = TYPES.map((t) => `<label><input type="checkbox" value="${esc(t)}"> ${esc(t)}</label>`).join('');
    const stages = [...new Set(P.map((p) => p.stageGroup))].sort();
    $('#fStage').innerHTML = '<option value="">All stages</option>' + stages.map((s) => `<option>${esc(s)}</option>`).join('');
    fillCountries();
    $$('#fRegion input').forEach((i) => i.addEventListener('change', () => { F.regions = new Set($$('#fRegion input:checked').map((x) => x.value)); F.country = ''; F.airport = ''; fillCountries(); render(); }));
    $$('#fType input').forEach((i) => i.addEventListener('change', () => { F.types = new Set($$('#fType input:checked').map((x) => x.value)); render(); }));
    $('#fSearch').addEventListener('input', (e) => { F.search = e.target.value.trim().toLowerCase(); render(); });
    $('#fCountry').addEventListener('change', (e) => { F.country = e.target.value; F.airport = ''; fillAirports(); render(); });
    $('#fAirport').addEventListener('change', (e) => { F.airport = e.target.value; render(); });
    $('#fStage').addEventListener('change', (e) => { F.stage = e.target.value; render(); });
    $('#fProc').addEventListener('change', (e) => { F.proc = e.target.value; render(); });
    $('#fPriority').addEventListener('change', (e) => { F.priority = e.target.value; render(); });
    $('#fSince').addEventListener('change', (e) => { F.since = e.target.value; render(); });
    $('#fFlagged').addEventListener('change', (e) => { F.flagged = e.target.checked; render(); });
    $('#fContext').addEventListener('change', (e) => { F.context = e.target.checked; render(); });
    $('#clearFilters').addEventListener('click', () => {
      Object.assign(F, { search: '', regions: new Set(), country: '', airport: '', types: new Set(), stage: '', proc: '', priority: '', since: '', flagged: false, context: true });
      $$('#fRegion input, #fType input').forEach((i) => (i.checked = false));
      $('#fSearch').value = ''; $('#fStage').value = ''; $('#fProc').value = ''; $('#fPriority').value = ''; $('#fSince').value = ''; $('#fFlagged').checked = false; $('#fContext').checked = true;
      fillCountries(); render();
    });
  }
  function fillCountries() {
    const pool = P.filter((p) => !F.regions.size || F.regions.has(p.region));
    const cs = [...new Set(pool.map((p) => p.country))].sort();
    $('#fCountry').innerHTML = '<option value="">All countries</option>' + cs.map((c) => `<option ${c === F.country ? 'selected' : ''}>${esc(c)}</option>`).join('');
    fillAirports();
  }
  function fillAirports() {
    const pool = P.filter((p) => (!F.regions.size || F.regions.has(p.region)) && (!F.country || p.country === F.country));
    const as = [...new Set(pool.map((p) => p.airport))].sort();
    $('#fAirport').innerHTML = '<option value="">All airports</option>' + as.map((a) => `<option ${a === F.airport ? 'selected' : ''}>${esc(a)}</option>`).join('');
  }
  function filtered() {
    const since = F.since ? parseDate(F.since) : null;
    return P.filter((p) => {
      if (!F.context && !p.active) return false;
      if (F.regions.size && !F.regions.has(p.region)) return false;
      if (F.country && p.country !== F.country) return false;
      if (F.airport && p.airport !== F.airport) return false;
      if (F.types.size && !(p.types || []).some((t) => F.types.has(t))) return false;
      if (F.stage && p.stageGroup !== F.stage) return false;
      if (F.proc && p.procKind !== F.proc) return false;
      if (F.priority && p.priority !== F.priority) return false;
      if (since && (!p.latest || p.latest < since)) return false;
      if (F.flagged && !p.flags.length) return false;
      if (F.search) {
        const hay = [p.name, p.airport, p.iata, p.city, p.country, p.region, p.owner, p.scope, (p.parties && p.parties.consultants || []).join(' ')].join(' ').toLowerCase();
        if (!hay.includes(F.search)) return false;
      }
      return true;
    });
  }

  // ---------- Sorting ----------
  let sortKey = 'score', sortDir = -1;
  const sorters = {
    score: (a, b) => (a.active - b.active) || (a.total - b.total),
    name: (a, b) => a.name.localeCompare(b.name),
    country: (a, b) => a.country.localeCompare(b.country) || a.name.localeCompare(b.name),
    stage: (a, b) => a.stageGroup.localeCompare(b.stageGroup),
    value: (a, b) => a.usd - b.usd,
    update: (a, b) => (a.latest || 0) - (b.latest || 0),
    milestone: (a, b) => ((a.next ? a.next.dt : Infinity) - (b.next ? b.next.dt : Infinity))
  };
  function sorted(list) {
    const fn = sorters[sortKey] || sorters.score;
    if (sortKey === 'milestone') return list.slice().sort(fn);
    const out = list.slice().sort(fn);
    if (sortDir < 0) out.reverse();
    return out;
  }
  $('#sortBy').addEventListener('change', (e) => { const [k, d] = e.target.value.split('-'); sortKey = k; sortDir = d === 'desc' ? -1 : 1; render(); });
  $$('#projectTable th[data-sort]').forEach((th) => th.addEventListener('click', () => { const k = th.dataset.sort; if (sortKey === k) sortDir = -sortDir; else { sortKey = k; sortDir = /^(name|country|stage|milestone)$/.test(k) ? 1 : -1; } render(); }));

  // ---------- Formatting ----------
  function valueText(p) {
    const v = p.value || {};
    if (!v.amount || !v.currency) return '<span class="muted">Not publicly disclosed</span>';
    const unitTxt = { bn: 'bn', m: 'm', tn: 'tn', cr: 'crore' }[v.unit] || v.unit || '';
    return `<span class="num">${esc(v.currency)} ${esc(v.amount)}${esc(unitTxt)}</span>`;
  }
  function procPill(p) {
    const cls = p.procKind === 'confirmed' ? 'pill pill-open' : 'pill';
    const label = { confirmed: 'Confirmed activity', potential: 'Potential', existing: 'Existing engagement', track: 'Track only' }[p.procKind];
    return `<span class="${cls}">${label}</span>`;
  }
  function flagPills(p) {
    const items = p.flags.map((f) => `<span class="pill ${/conflict|cancel|sanction|risk/i.test(f) ? 'pill-flag' : 'pill-warn'}">${esc(f.length > 42 ? f.slice(0, 40) + '…' : f)}</span>`);
    if (p.signals.length) items.unshift(`<span class="pill pill-signal">${p.signals.length} new source signal${p.signals.length > 1 ? 's' : ''} to review</span>`);
    return items.length ? `<div class="flags">${items.join('')}</div>` : '';
  }

  // ---------- Render ----------
  function render() {
    const list = filtered();
    renderKpis(list);
    renderTable(sorted(list));
    renderMap(list);
    renderCalendar(list);
    renderFeed(list);
    const parts = [];
    if (F.regions.size) parts.push([...F.regions].join(', '));
    if (F.country) parts.push(F.country);
    if (F.airport) parts.push(F.airport);
    if (F.types.size) parts.push([...F.types].join(' | '));
    if (F.stage) parts.push(F.stage);
    if (F.proc) parts.push(F.proc);
    if (F.priority) parts.push(F.priority);
    if (F.since) parts.push('updated since ' + F.since);
    if (F.search) parts.push('"' + F.search + '"');
    $('#filterSummary').textContent = `${list.length} of ${P.length} records` + (parts.length ? ' · ' + parts.join(' · ') : '');
  }
  function renderKpis(list) {
    const active = list.filter((p) => p.active);
    $('#kpiActive').textContent = active.length;
    $('#kpiActiveNote').textContent = `of ${P.filter((p) => p.active).length} active records in total`;
    $('#kpiNew').textContent = active.filter((p) => p.isNew).length;
    $('#kpiOpen').textContent = active.filter((p) => p.procKind === 'confirmed').length;
    const horizon = new Date(TODAY.getTime() + 90 * DAY);
    const due = active.filter((p) => p.ms.some((m) => m.dt >= TODAY && m.dt <= horizon));
    $('#kpiDeadlines').textContent = due.length;
    const overdue = active.filter((p) => p.overdue.length).length;
    $('#kpiDeadNote').textContent = `projects with a dated milestone due by ${fmtDate(horizon.toISOString().slice(0, 10))}` + (overdue ? `; ${overdue} overdue to verify` : '');
    $('#kpiHigh').textContent = active.filter((p) => p.priority === 'High').length;
    $('#kpiContext').textContent = list.filter((p) => !p.active).length;
  }
  function renderTable(list) {
    $('#resultCount').textContent = `${list.length} project${list.length === 1 ? '' : 's'} shown (${list.filter((p) => p.active).length} active, ${list.filter((p) => !p.active).length} context)`;
    $('#projectRows').innerHTML = list.map((p) => `
      <tr data-id="${esc(p.id)}" tabindex="0">
        <td><span class="score score-${p.priority}" title="${p.active ? 'Priority score out of 20' : 'Not scored'}">${p.active ? p.total : 'Context'}</span></td>
        <td><div class="cell-name">${esc(p.name)}</div><div class="cell-sub"><span class="mono">${esc(p.iata)}</span> · ${esc(p.airport)}${p.isNew ? ' · <span class="pill">New</span>' : ''}</div>${flagPills(p)}</td>
        <td>${esc(p.country)}<div class="cell-sub">${esc(p.region)}</div></td>
        <td>${esc(p.stageGroup)}<div class="cell-sub">${esc(p.stage)}</div></td>
        <td>${procPill(p)}<div class="cell-sub">${esc((p.procurement_status || '').slice(0, 90))}${(p.procurement_status || '').length > 90 ? '…' : ''}</div></td>
        <td>${valueText(p)}<div class="cell-sub">${esc((p.value && p.value.basis || '').slice(0, 60))}</div></td>
        <td class="num">${esc(fmtDate(p.dates && p.dates.latest_update))}</td>
        <td>${p.next ? `<span class="num">${esc(p.next.when || fmtDate(p.next.date))}</span><div class="cell-sub">${esc(p.next.label)}</div>` : '<span class="cell-sub">None dated</span>'}</td>
      </tr>`).join('');
    $$('#projectRows tr').forEach((tr) => { tr.addEventListener('click', () => openDrawer(tr.dataset.id)); tr.addEventListener('keydown', (e) => { if (e.key === 'Enter') openDrawer(tr.dataset.id); }); });
  }

  // ---------- Map ----------
  const svg = $('#worldMap');
  const NS = 'http://www.w3.org/2000/svg';
  const REGION_BOX = { World: [0, 0, 1000, 500], Europe: [-14, 33, 48, 63], 'Middle East': [30, 10, 62, 40], 'North Africa': [-18, 18, 40, 40], 'Central Asia': [40, 33, 90, 56], 'Asia Pacific': [65, -48, 180, 48], Australia: [110, -46, 158, -8], 'North America': [-130, 12, -55, 60] };
  function proj(lon, lat) { return [(lon + 180) / 360 * 1000, (90 - lat) / 180 * 500]; }
  function initMap() {
    const land = document.createElementNS(NS, 'path'); land.setAttribute('class', 'land'); land.setAttribute('d', window.AMI_WORLD_PATH || ''); svg.appendChild(land);
    const g = document.createElementNS(NS, 'g'); g.id = 'markers'; svg.appendChild(g);
    $$('#mapZoom button').forEach((b) => b.addEventListener('click', () => { $$('#mapZoom button').forEach((x) => x.classList.remove('is-active')); b.classList.add('is-active'); setView(b.dataset.region); }));
    setView('World');
  }
  let curScale = 1;
  function setView(region) {
    const b = REGION_BOX[region];
    if (region === 'World') { svg.setAttribute('viewBox', '0 0 1000 500'); curScale = 1; }
    else {
      const [x0, y1] = proj(b[0], b[3]); const [x1, y0] = proj(b[2], b[1]);
      let w = x1 - x0, h = y0 - y1;
      if (w / h > 2) h = w / 2; else w = h * 2;
      const cx = (x0 + x1) / 2, cy = (y0 + y1) / 2;
      svg.setAttribute('viewBox', `${cx - w / 2} ${cy - h / 2} ${w} ${h}`); curScale = 1000 / w;
    }
    renderMap(filtered());
  }
  function renderMap(list) {
    const g = $('#markers'); if (!g) return; g.innerHTML = '';
    const tip = $('#mapTip');
    list.slice().sort((a, b) => b.usd - a.usd).forEach((p) => {
      if (typeof p.lat !== 'number') return;
      const [x, y] = proj(p.lon, p.lat);
      const band = p.usd >= 5e9 ? 4 : p.usd >= 1e9 ? 3 : p.usd >= 3e8 ? 2 : 1;
      const c = document.createElementNS(NS, 'circle');
      c.setAttribute('cx', x); c.setAttribute('cy', y); c.setAttribute('r', (3 + band * 1.3) / Math.sqrt(curScale)); c.setAttribute('class', `marker m-${p.priority}`);
      c.addEventListener('mouseenter', () => { tip.hidden = false; tip.innerHTML = `<b>${esc(p.name)}</b><br>${esc(p.country)} · ${esc(p.stageGroup)}<br>${p.active ? 'Score ' + p.total + ' (' + p.priority + ')' : 'Context record'}`; });
      c.addEventListener('mousemove', (e) => { const r = $('.map-frame').getBoundingClientRect(); tip.style.left = Math.min(e.clientX - r.left + 14, r.width - 290) + 'px'; tip.style.top = (e.clientY - r.top + 14) + 'px'; });
      c.addEventListener('mouseleave', () => (tip.hidden = true));
      c.addEventListener('click', () => openDrawer(p.id));
      g.appendChild(c);
    });
  }

  // ---------- Calendar ----------
  function renderCalendar(list) {
    const items = [];
    list.forEach((p) => p.ms.forEach((m) => items.push({ ...m, p })));
    const horizon = new Date(TODAY.getTime() + 548 * DAY);
    const upcoming = items.filter((i) => i.dt >= TODAY && i.dt <= horizon).sort((a, b) => a.dt - b.dt);
    const overdue = items.filter((i) => i.dt < TODAY && /overdue|verify/i.test(i.when || ''));
    $('#calCount').textContent = `${upcoming.length} milestones in the next 18 months across ${new Set(upcoming.map((i) => i.p.id)).size} projects` + (overdue.length ? `; ${overdue.length} overdue to verify` : '');
    const groups = {};
    upcoming.forEach((i) => { const k = i.dt.getFullYear() + '-' + String(i.dt.getMonth() + 1).padStart(2, '0'); (groups[k] = groups[k] || []).push(i); });
    const item = (i) => `<div class="cal-item ${i.dt < TODAY ? 'overdue' : ''}" data-id="${esc(i.p.id)}"><div class="cal-bar ${esc(i.kind)}"></div><div class="cal-when">${esc(i.when || fmtDate(i.date))}${i.approx ? '<br><span style="color:var(--muted)">approx.</span>' : ''}</div><div class="cal-what"><b>${esc(i.label)}</b><span>${esc(i.p.name)} · ${esc(i.p.country)}</span></div></div>`;
    let html = '';
    if (overdue.length) html += `<div class="cal-month"><h3 style="color:var(--crit)">Overdue - verify</h3><div class="cal-items">${overdue.map(item).join('')}</div></div>`;
    html += Object.keys(groups).sort().map((k) => `<div class="cal-month"><h3>${esc(fmtDate(k))}</h3><div class="cal-items">${groups[k].map(item).join('')}</div></div>`).join('');
    $('#calendarList').innerHTML = html || '<p class="fine">No dated milestones in the current filter.</p>';
    $$('#calendarList .cal-item').forEach((el) => el.addEventListener('click', () => openDrawer(el.dataset.id)));
  }

  // ---------- Feed and signals ----------
  function signalItem(s, p) {
    const dismiss = LOCAL ? `<button class="link-btn dismiss" data-link="${esc(s.link)}" type="button">Mark reviewed</button>` : '';
    return `<div class="signal-item"><div class="feed-date">${esc(fmtDate(s.first_seen))}<br><span style="color:var(--muted)">seen</span></div><div>${p ? `<b>${esc(p.name)}</b> <span class="pill">${esc(p.region)}</span><br>` : ''}<a href="${esc(s.link)}" target="_blank" rel="noopener">${esc(s.title)}</a><div class="src">${esc(s.source)}${s.published ? ' · ' + esc(s.published) : ''}</div></div><div>${dismiss}</div></div>`;
  }
  function bindDismiss(root) {
    $$('.dismiss', root).forEach((b) => b.addEventListener('click', async (e) => {
      e.stopPropagation();
      b.disabled = true;
      try {
        const r = await fetch('/api/dismiss', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ link: b.dataset.link }) });
        if (!r.ok) throw new Error(r.status);
        await reloadData();
      } catch (err) { b.disabled = false; alert('Could not mark reviewed: ' + err.message); }
    }));
  }
  function renderFeed(list) {
    const since = parseDate($('#feedSince').value) || new Date(TODAY - 180 * DAY);
    const ev = [];
    list.forEach((p) => (p.history || []).forEach((h) => { const dt = parseDate(h.date); if (dt && dt >= since) ev.push({ ...h, dt, p }); }));
    ev.sort((a, b) => b.dt - a.dt);
    $('#feedCount').textContent = `${ev.length} material developments since ${fmtDate(since.toISOString().slice(0, 10))} (history entries only; republished articles are not counted)`;
    $('#feedList').innerHTML = ev.map((e) => { const s = e.p.sources && e.p.sources[e.source]; return `<div class="feed-item" data-id="${esc(e.p.id)}"><div class="feed-date">${esc(fmtDate(e.date))}</div><div><b>${esc(e.p.name)}</b> <span class="pill">${esc(e.p.region)}</span><p>${esc(e.event)}</p>${s ? `<div class="src">Source: ${esc(s.publisher)}${s.date ? ', ' + esc(fmtDate(s.date)) : ''}</div>` : ''}</div></div>`; }).join('') || '<p class="fine">No developments in this window.</p>';
    $$('#feedList .feed-item').forEach((el) => el.addEventListener('click', () => openDrawer(el.dataset.id)));
    const sig = [];
    list.forEach((p) => p.signals.forEach((s) => sig.push({ s, p })));
    sig.sort((a, b) => (b.s.first_seen || '').localeCompare(a.s.first_seen || ''));
    $('#signalList').innerHTML = sig.map(({ s, p }) => signalItem(s, p)).join('') || '<p class="fine">No unreviewed signals in the current filter.</p>';
    const un = SIGNALS.unmatched || [];
    $('#unmatchedList').innerHTML = un.map((s) => signalItem(s, null)).join('') || '<p class="fine">None pending.</p>';
    bindDismiss($('#signalList')); bindDismiss($('#unmatchedList'));
  }
  $('#feedSince').addEventListener('change', () => renderFeed(filtered()));

  // ---------- Sources & refresh status ----------
  function renderSources() {
    const st = REFRESH;
    const warn = !st.last_scan || (Date.now() - new Date(st.last_scan)) > 2 * DAY;
    const sigCount = P.reduce((n, p) => n + p.signals.length, 0) + (SIGNALS.unmatched || []).length;
    $('#refreshText').textContent = (st.last_scan ? `Scanned ${fmtStamp(st.last_scan)} · ${st.schedule || 'manual'}` : 'No scan recorded') + (sigCount ? ` · ${sigCount} signals to review` : '');
    $('#refreshChip').classList.toggle('is-warn', warn);
    const okFeeds = (st.feeds || []).filter((f) => String(f.status) === '200').length;
    $('#refreshStatus').innerHTML = [
      ['Last scan ran', fmtStamp(st.last_scan)],
      ['Scan mode', st.scan_mode || ''],
      ['Schedule', st.schedule || 'Manual'],
      ['Feeds reachable', st.feeds && st.feeds.length ? `${okFeeds} of ${st.feeds.length}` : 'No automated feed scan yet'],
      ['Signals awaiting review', String(sigCount)],
      ['Records flagged stale (>180 days)', String(P.filter((p) => p.flags.some((f) => /stale/i.test(f))).length)]
    ].map(([l, v]) => `<div class="status-card"><div class="lab">${esc(l)}</div><div class="val">${esc(v)}</div></div>`).join('') + `<div class="status-card" style="grid-column:1/-1"><div class="lab">Note</div><div class="val" style="font-family:var(--font-body)">${esc(st.note || '')}</div></div>`;
    $('#feedStatusWrap').innerHTML = st.feeds && st.feeds.length ? `<table class="grid compact"><thead><tr><th>Feed</th><th>Kind</th><th>HTTP</th><th>Items</th><th>Error</th></tr></thead><tbody>${st.feeds.map((f) => `<tr><td>${esc(f.name)}</td><td>${esc(f.kind)}</td><td class="num">${esc(f.status)}</td><td class="num">${esc(f.items)}</td><td>${esc(f.error || '')}</td></tr>`).join('')}</tbody></table>` : '';
    $('#sourceTable tbody').innerHTML = (SOURCES.sources || []).map((s) => `<tr><td><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.name)}</a></td><td>${esc(s.type)}</td><td>${esc(s.feed_status)}</td><td>${esc(s.page_status)}</td><td>${esc(s.coverage)}</td><td class="num">${esc(s.used_for)}</td></tr>`).join('');
    $('#gapList').innerHTML = (SOURCES.gaps || []).map((g) => `<li>${esc(g)}</li>`).join('');
  }

  // ---------- Manual refresh ----------
  const modal = $('#refreshModal'), modalBack = $('#refreshModalBackdrop'), modalBody = $('#refreshBody');
  function showModal(html) { modalBody.innerHTML = html; modal.hidden = false; modalBack.hidden = false; }
  function hideModal() { modal.hidden = true; modalBack.hidden = true; }
  $('#closeRefresh').addEventListener('click', hideModal); modalBack.addEventListener('click', hideModal);
  async function fetchJson(path) { const r = await fetch(path + '?t=' + Date.now(), { cache: 'no-store' }); if (!r.ok) throw new Error(`${path}: HTTP ${r.status}`); return r.json(); }
  async function reloadData() {
    const [projects, sources, refresh, signals] = await Promise.all([fetchJson('data/projects.json'), fetchJson('data/sources.json'), fetchJson('data/refresh_status.json'), fetchJson('data/signals.json').catch(() => ({ projects: {}, unmatched: [], dismissed: [] }))]);
    RAW = projects; SOURCES = sources; REFRESH = refresh; SIGNALS = signals;
    derive(); renderSources(); render();
    if (!$('#drawer').hidden && currentId) openDrawer(currentId);
  }
  $('#refreshBtn').addEventListener('click', async () => {
    if (!LOCAL) {
      const cfg = window.AMI_CONFIG || {};
      if (cfg.refresh_workflow_url) {
        showModal(`<p><b>This hosted copy is refreshed by a scheduled scan</b>${cfg.schedule_note ? ' (' + esc(cfg.schedule_note) + ')' : ''}. Last scan: <span class="mono">${esc(fmtStamp(REFRESH.last_scan))}</span>.</p>
          <p>To run it now, open the scan workflow and press <b>Run workflow</b>. The page updates itself a few minutes after the run finishes; reload to see the new signals.</p>
          <p><a class="btn" href="${esc(cfg.refresh_workflow_url)}" target="_blank" rel="noopener" style="display:inline-block;text-decoration:none">Open scan workflow</a></p>
          <p>Try reloading first if you expect a recent scan: <button class="link-btn" id="reloadNow" type="button">Reload latest data</button></p>`);
        const rl = $('#reloadNow'); if (rl) rl.addEventListener('click', async () => { rl.disabled = true; try { await reloadData(); hideModal(); } catch (e) { rl.disabled = false; alert('Reload failed: ' + e.message); } });
        return;
      }
      showModal(`<p><b>This page is a hosted copy, which cannot reach news feeds.</b> The hosting sandbox blocks outbound requests, so a live scan has to run on a machine with network access.</p>
        <p>Last scan: <span class="mono">${esc(fmtStamp(REFRESH.last_scan))}</span> (${esc(REFRESH.schedule || 'manual')}).</p>
        <p>To run a scan now, open the local copy of the dashboard (served by the included local server) and press Refresh scan there, or run:</p>
        <pre>powershell -ExecutionPolicy Bypass -File refresh\\Refresh-Feeds.ps1</pre>
        <p>Then republish this copy with the updated <span class="mono">data/</span> files. For automatic daily scans on a hosted site, see DEPLOY.md (GitHub Pages plus a scheduled workflow).</p>`);
      return;
    }
    const btn = $('#refreshBtn'); btn.disabled = true;
    showModal('<p><span class="spin"></span>Scanning configured feeds and pages. This takes about a minute.</p>');
    const before = { sig: P.reduce((n, p) => n + p.signals.length, 0), un: (SIGNALS.unmatched || []).length };
    try {
      const r = await fetch('/api/refresh', { method: 'POST' });
      if (!r.ok) throw new Error('HTTP ' + r.status);
      const res = await r.json();
      await reloadData();
      const st = res.status || {};
      const ok = (st.feeds || []).filter((f) => String(f.status) === '200').length;
      const touched = (st.projects_with_new_signals || []).map((id) => byId[id]).filter(Boolean);
      const newSig = st.new_signals_this_run | 0, newUn = st.new_unmatched_this_run | 0;
      const failed = (st.feeds || []).filter((f) => String(f.status) !== '200');
      showModal(`<p><b>Scan complete</b> at <span class="mono">${esc(fmtStamp(st.last_scan))}</span>.</p>
        <div class="stat-row"><div class="stat">Feeds reachable<b>${ok} / ${(st.feeds || []).length}</b></div><div class="stat">New signals on tracked projects<b>${newSig}</b></div><div class="stat">Possible new projects<b>${newUn}</b></div><div class="stat">Stale records<b>${(st.stale_projects || []).length}</b></div></div>
        ${newSig || newUn ? `<p>${touched.length ? 'Records updated with unreviewed signals: ' + touched.map((p) => `<a href="#" data-open="${esc(p.id)}">${esc(p.name)}</a>`).join('; ') + '.' : ''} Open the <b>New and changed</b> tab to review them; verified fields change only after you confirm a development in the data files.</p>` : '<p>No new coverage of tracked airports since the last scan. Records are unchanged.</p>'}
        ${failed.length ? `<p>Unreachable this run: ${failed.map((f) => esc(f.name) + ' (' + esc(f.status) + ')').join(', ')}.</p>` : ''}
        <details><summary>Scan log</summary><pre>${esc(res.log || '')}</pre></details>`);
      $$('#refreshBody a[data-open]').forEach((a) => a.addEventListener('click', (e) => { e.preventDefault(); hideModal(); openDrawer(a.dataset.open); }));
      void before;
    } catch (err) {
      showModal(`<p><b>Refresh failed:</b> ${esc(err.message)}.</p><p>Make sure the page is served by <span class="mono">refresh\\Serve-Local.ps1</span> (it exposes the refresh endpoint) and that the machine has network access. You can also run <span class="mono">refresh\\Refresh-Feeds.ps1</span> directly and reload this page.</p>`);
    } finally { btn.disabled = false; }
  });

  // ---------- Drawer ----------
  let currentId = null;
  function openDrawer(id) {
    const p = byId[id]; if (!p) return;
    currentId = id;
    $('#dKicker').textContent = `${p.id} · ${p.iata} · ${p.airport} · ${p.city}, ${p.country} · ${p.region}`;
    $('#dTitle').textContent = p.name;
    $('#dBadges').innerHTML = [
      `<span class="score score-${p.priority}">${p.active ? p.total + ' / 20 · ' + p.priority : 'Context'}</span>`,
      `<span class="pill">${esc(p.stageGroup)}</span>`, procPill(p), `<span class="pill">Confidence: ${esc(p.confidence)}</span>`,
      ...(p.signals.length ? [`<span class="pill pill-signal">${p.signals.length} signal${p.signals.length > 1 ? 's' : ''} to review</span>`] : []),
      ...p.flags.map((f) => `<span class="pill ${/conflict|cancel|sanction|risk/i.test(f) ? 'pill-flag' : 'pill-warn'}">${esc(f)}</span>`)
    ].join('');
    const d = p.dates || {}, pt = p.parties || {}, v = p.value || {};
    const kv = (rows) => `<dl class="kv">${rows.map(([k, val, cls]) => `<dt>${esc(k)}</dt><dd class="${cls || ''}">${val}</dd>`).join('')}</dl>`;
    const list = (arr) => arr && arr.length ? esc(arr.join('; ')) : '<span class="muted">Not publicly disclosed</span>';
    const s = p.score || {};
    const bars = [['Service fit', s.fit], ['Procurement timing', s.timing], ['Accessibility', s.access], ['Scale', s.scale], ['Evidence quality', s.evidence]];
    $('#dBody').innerHTML = `
      ${p.signals.length ? `<div class="sec"><h3 class="sec-h"><span class="tag tag-judge">Unreviewed</span> Source signals from the feed scan</h3><p class="fine" style="margin:0 0 8px">New coverage that mentions this airport. Confirm whether it is a material development before updating the record.</p><div class="feed">${p.signals.map((sg) => signalItem(sg, null)).join('')}</div></div>` : ''}
      <div class="sec"><h3 class="sec-h"><span class="tag tag-fact">Sourced</span> Scope and status</h3>
        ${kv([
          ['Scope', esc(p.scope)], ['Capacity', esc(nd(p.capacity))], ['Project types', esc((p.types || []).join(', '))],
          ['Stage', esc(p.stage)], ['Procurement status', esc(p.procurement_status)], ['Delivery / financing', esc(nd(p.delivery_model))],
          ['Reported value', v.amount ? `${esc(v.currency)} ${esc(v.amount)}${esc({ bn: 'bn', m: 'm', tn: 'tn', cr: ' crore' }[v.unit] || v.unit || '')} <span class="cell-sub">${esc(v.basis || '')}${v.source_note ? ' (' + esc(v.source_note) + ')' : ''}</span>` : `<span class="muted">Not publicly disclosed</span>${v.basis ? ' <span class="cell-sub">' + esc(v.basis) + '</span>' : ''}`],
          ['Contract values', (p.contracts || []).length ? `<ul class="ms-list">${p.contracts.map((c) => `<li><b>${esc(c.package)}</b>: ${esc(c.value)} - ${esc(c.holder)}${c.date ? ' (' + esc(fmtDate(c.date)) + ')' : ''}</li>`).join('')}</ul>` : '<span class="muted">None recorded</span>']
        ])}
      </div>
      <div class="sec"><h3 class="sec-h"><span class="tag tag-fact">Sourced</span> Parties</h3>
        ${kv([['Owner', esc(nd(p.owner))], ['Operator', esc(nd(p.operator))], ['Developer', esc(nd(p.developer))], ['Procuring authority', esc(nd(p.procuring_authority))], ['Consultants', list(pt.consultants)], ['Contractors', list(pt.contractors)], ['Investors / funders', list(pt.investors)], ['Business contact', esc(nd(p.contact))]])}
      </div>
      <div class="sec"><h3 class="sec-h"><span class="tag tag-fact">Sourced</span> Dates</h3>
        ${kv([['Announced', esc(fmtDate(d.announced) || nd(''))], ['Latest substantive update', `<span class="num">${esc(fmtDate(d.latest_update))}</span>${p.staleDays != null ? ` <span class="cell-sub">${p.staleDays} days ago</span>` : ''}`], ['Expected procurement', esc(nd(d.expected_procurement))], ['Construction', esc(nd(d.construction_start))], ['Completion target', esc(nd(d.completion_target))], ['Milestones', p.ms.length ? `<ul class="ms-list">${p.ms.map((m) => `<li><span class="num">${esc(m.when || fmtDate(m.date))}</span> - ${esc(m.label)} <span class="pill">${esc(m.kind)}</span></li>`).join('')}</ul>` : '<span class="muted">None dated</span>'], ['First identified', esc(fmtDate(p.first_identified))], ['Last verified', esc(fmtDate(p.last_verified))]])}
      </div>
      <div class="sec"><h3 class="sec-h"><span class="tag tag-judge">Analyst judgment</span> Business development assessment</h3>
        ${p.active ? `<div class="scorebars">${bars.map(([l, n]) => `<span>${esc(l)}</span><div class="bar"><i style="width:${(n | 0) * 25}%"></i></div><span class="n">${n | 0}/4</span>`).join('')}<span><b>Total</b></span><div></div><span class="n"><b>${p.total}/20</b></span></div>` : '<p class="fine">Not scored: completed, cancelled or suspended record kept for context.</p>'}
        <p style="margin:10px 0 6px"><b>Opportunity type:</b> ${esc(p.opportunity_type)}</p>
        <p style="margin:0 0 10px"><b>Rationale:</b> ${esc(p.rationale)}</p>
        <p style="margin:0 0 6px"><b>Potential SJ Group services</b> (mapping of scope to verified capabilities):</p>
        <div class="chips">${(p.sj_services || []).length ? p.sj_services.map((x) => `<span class="pill">${esc(x)}</span>`).join('') : '<span class="muted">None identified</span>'}</div>
        <div class="callout next" style="margin-top:12px"><b>Recommended next action:</b> ${esc(p.next_action)}</div>
      </div>
      <div class="sec"><h3 class="sec-h">Update history</h3>
        <ul class="timeline">${(p.history || []).slice().sort((a, b) => (parseDate(b.date) || 0) - (parseDate(a.date) || 0)).map((h) => { const src = p.sources && p.sources[h.source]; return `<li><span class="d">${esc(fmtDate(h.date))}</span>${esc(h.event)}${src ? ` <span class="cell-sub">[${esc(src.publisher)}]</span>` : ''}</li>`; }).join('')}</ul>
      </div>
      <div class="sec"><h3 class="sec-h">Sources (${(p.sources || []).length})</h3>
        <ul class="srcs">${(p.sources || []).map((s) => `<li><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)}</a><div class="meta">${esc(s.publisher)} · ${esc(s.type)} · published ${esc(fmtDate(s.date) || s.date || 'n.d.')} · ${esc(s.access)}</div></li>`).join('')}</ul>
      </div>`;
    bindDismiss($('#dBody'));
    $('#drawer').hidden = false; $('#drawerBackdrop').hidden = false; $('#drawer .drawer-body').scrollTop = 0; $('#closeDrawer').focus();
  }
  function closeDrawer() { $('#drawer').hidden = true; $('#drawerBackdrop').hidden = true; currentId = null; }
  $('#closeDrawer').addEventListener('click', closeDrawer);
  $('#drawerBackdrop').addEventListener('click', closeDrawer);
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape') { closeDrawer(); hideModal(); } });

  // ---------- Tabs ----------
  $$('.tab').forEach((t) => t.addEventListener('click', () => {
    $$('.tab').forEach((x) => x.classList.toggle('is-active', x === t));
    $$('.panel').forEach((pn) => (pn.hidden = pn.id !== 'tab-' + t.dataset.tab));
  }));

  // ---------- CSV ----------
  function csvEscape(s) { s = String(s == null ? '' : s); return /[",\n\r]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; }
  function buildCsv(list) {
    const cols = ['id', 'name', 'airport', 'iata', 'city', 'country', 'region', 'types', 'stage', 'stage_group', 'active', 'procurement_status', 'opportunity_type', 'delivery_model', 'owner', 'operator', 'developer', 'procuring_authority', 'scope', 'capacity', 'value_amount', 'value_unit', 'value_currency', 'value_basis', 'contracts', 'announced', 'latest_update', 'expected_procurement', 'construction_start', 'completion_target', 'next_milestone_when', 'next_milestone', 'consultants', 'contractors', 'investors', 'sj_services', 'contact', 'confidence', 'score_fit', 'score_timing', 'score_access', 'score_scale', 'score_evidence', 'score_total', 'priority', 'rationale', 'next_action', 'flags', 'unreviewed_signals', 'sources', 'first_identified', 'last_verified'];
    const rows = list.map((p) => [p.id, p.name, p.airport, p.iata, p.city, p.country, p.region, (p.types || []).join('; '), p.stage, p.stageGroup, p.active ? 'yes' : 'no', p.procurement_status, p.opportunity_type, p.delivery_model, p.owner, p.operator, p.developer, p.procuring_authority, p.scope, p.capacity, p.value && p.value.amount, p.value && p.value.unit, p.value && p.value.currency, p.value && p.value.basis, (p.contracts || []).map((c) => `${c.package}: ${c.value} - ${c.holder}`).join(' | '), p.dates.announced, p.dates.latest_update, p.dates.expected_procurement, p.dates.construction_start, p.dates.completion_target, p.next ? p.next.when : '', p.next ? p.next.label : '', (p.parties.consultants || []).join('; '), (p.parties.contractors || []).join('; '), (p.parties.investors || []).join('; '), (p.sj_services || []).join('; '), p.contact, p.confidence, p.score.fit, p.score.timing, p.score.access, p.score.scale, p.score.evidence, p.active ? p.total : '', p.priority, p.rationale, p.next_action, p.flags.join(' | '), p.signals.map((s) => `${s.title}: ${s.link}`).join(' | '), (p.sources || []).map((s) => `${s.publisher} (${s.date}): ${s.url}`).join(' | '), p.first_identified, p.last_verified]);
    return '﻿' + [cols, ...rows].map((r) => r.map(csvEscape).join(',')).join('\r\n');
  }
  $('#exportCsv').addEventListener('click', () => {
    const csv = buildCsv(sorted(filtered()));
    const name = `airport-projects-${new Date().toISOString().slice(0, 10)}.csv`;
    try { const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' })); a.download = name; document.body.appendChild(a); a.click(); a.remove(); } catch (e) { /* fall through */ }
    $('#csvText').value = csv; $('#csvFallback').hidden = false;
  });
  $('#copyCsv').addEventListener('click', () => { $('#csvText').select(); try { navigator.clipboard.writeText($('#csvText').value); } catch (e) { document.execCommand('copy'); } });
  $('#closeCsv').addEventListener('click', () => ($('#csvFallback').hidden = true));

  // ---------- Init ----------
  derive(); buildFilterUI(); initMap(); renderSources(); render();
})();
